package vn.cinema.service;
import org.springframework.stereotype.Component;import org.springframework.scheduling.annotation.Scheduled;@Component public class PaymentJobs{private final PaymentService s;private final PayOSClient payos;public PaymentJobs(PaymentService s,PayOSClient payos){this.s=s;this.payos=payos;}@Scheduled(fixedDelay=5000)public void reconcile(){if(!payos.configured())return;for(long id:s.pending()){try{s.reconcile(id);}catch(RuntimeException e){org.slf4j.LoggerFactory.getLogger(getClass()).warn("Payment reconciliation will retry for {}: {}",id,e.getMessage());}}}}
